const SHEET_ID = '1dl7hNofQp8v57h1Veodd3XqFctJxAvgAA2qXVtnE1ZU';
const HOJAS = {
 'Fundas a medida':877828453,'TIPO TAPIZADO':613213257,'TAPICERIA':972378170,
 'Termoformadas':0,'Funda Baúl - Antiderrame':941782890,
 'Cobertores de caja ':2002506112,'ESPUMAS':1953604758,'Otros':59879218,
};
function validarContexto(raw) {
 if(raw?.modo==='simular')return {ok:true,contexto:{modo:'simular'}};
 if(raw?.modo!=='enviar'||raw.account_id!==1||!Number.isSafeInteger(raw.conversation_id)||raw.conversation_id<1)return {ok:false};
 const prefix=`cw:1:${raw.conversation_id}:`;
 if(typeof raw.solicitud_id!=='string'||!raw.solicitud_id.startsWith(prefix)||!/^cw:1:[1-9]\d*:[1-9]\d{0,31}:precios-v1$/.test(raw.solicitud_id))return {ok:false};
 return {ok:true,contexto:{modo:'enviar',account_id:1,conversation_id:raw.conversation_id,solicitud_id:raw.solicitud_id}};
}
function prepararRangos(titulos,metadata) {
 if(metadata?.spreadsheetId!==SHEET_ID||!Array.isArray(metadata.sheets))throw new Error('metadata_invalida');
 if(!Array.isArray(titulos)||!titulos.length||titulos.length>8)throw new Error('hojas_invalidas');
 return [...new Set(titulos)].map(title=>{
   if(!Object.hasOwn(HOJAS,title))throw new Error('hoja_no_permitida');
   const p=metadata.sheets.find(s=>s.properties?.sheetId===HOJAS[title])?.properties;
   if(!p||p.title!==title)throw new Error('estructura_de_hojas_cambio');
   const {rowCount:r,columnCount:c}=p.gridProperties??{};
   if(!Number.isSafeInteger(r)||r<1||!Number.isSafeInteger(c)||c<1||c>60||r*c>100000)throw new Error('dimensiones_fuera_de_limite');
   let col='',n=c;while(n){n--;col=String.fromCharCode(65+n%26)+col;n=Math.floor(n/26);}
   return {title,sheetId:p.sheetId,range:`'${title.replaceAll("'","''")}'!A1:${col}${r}`};
 });
}
function leerValores(body,rangos) {
 if(body?.spreadsheetId!==SHEET_ID||!Array.isArray(body.valueRanges)||body.valueRanges.length!==rangos.length)throw new Error('lectura_incompleta');
 return rangos.map((r,i)=>{
   const v=body.valueRanges[i];
   // Google puede omitir comillas cuando el título no las necesita.
   const title=String(v?.range??'').split('!').slice(0,-1).join('!').replace(/^'|'$/g,'').replaceAll("''","'");
   if(title!==r.title||!Array.isArray(v.values)||v.values.some(row=>!Array.isArray(row)))throw new Error('rango_o_valores_invalidos');
   return {...r,values:v.values};
 });
}
function evaluarEnvioTexto(response,contexto,contenido) {
 const incierto=motivo=>({estado:'desconocido',motivo,chatwoot_message_id:null});
 const status=Number(response?.statusCode??response?.error?.statusCode??response?.error?.httpCode);
 if(status>=400&&status<500&&status!==408)return {estado:'fallido',motivo:`http_${status}`,chatwoot_message_id:null};
 if(!Number.isInteger(status)||status<200||status>=300||response?.error)return incierto('envio_no_confirmado');
 const b=response.body;
 if(contexto?.account_id!==1||!Number.isSafeInteger(b?.id)||b.id<=0||b.conversation_id!==contexto.conversation_id||![1,'outgoing'].includes(b.message_type)||b.private!==false||b.content!==contenido)return incierto('respuesta_no_coincide');
 if(b.account_id!==undefined&&b.account_id!==1)return incierto('cuenta_no_coincide');
 if(b.status==='failed'||b.status===3||b.content_attributes?.external_error)return {estado:'fallido',motivo:'canal_rechazo_envio',chatwoot_message_id:b.id};
 return {estado:'aceptado',motivo:null,chatwoot_message_id:b.id};
}

// Evidencia de modalidad: exclusivamente texto humano suministrado por el caller.
const PREGUNTA_MODALIDAD = 'Hacemos envios a todo el pais y nuestro taller esta situado en CABA. Quisieras la opción de envio o colocarlo en nuestro taller?';

/** Historial ordenado de más antiguo a más nuevo. No acepta objetos ni mensajes de roles mezclados. */
function resolverModalidad(historialHuman, textoActual) {
  if (!Array.isArray(historialHuman) || historialHuman.some(t => typeof t !== 'string') || typeof textoActual !== 'string') return null;
  let elegida = null;
  for (const original of [...historialHuman.slice(-30), textoActual]) {
    if (original.length > 20000) return null;
    const normalizado = original.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
    // Afirmación corta: «sí envío» no es el condicional «si es fácil».
    const texto = normalizado.replace(/^si[\s,]+((?:(?:por|con) )?envio(?: a [a-z ]+)?|(?:en )?caba|(?:en el )?taller|con colocacion)[.!]*$/, (completo, eleccion) => /\b(?:me|te|se|sale|cuesta|gratis|es|tienen|puedo|necesito|quiero|debo|hay|seria|fuera|hacen)\b/.test(eleccion) ? completo : eleccion);
    const correccion = /\b(?:mejor|al final|en cambio|prefiero ahora|cambio a)\b/.test(texto);
    const opciones = [];
    const negadas = new Set();
    // Condicionales, dudas y citas valen dentro de la oración que menciona la modalidad:
    // «Si me puede hacer un presupuesto» en otra oración no anula «con envío».
    // Los puntos suspensivos no cortan la oración («Si es muy difícil....lo llevo al taller»).
    const oraciones = texto.split(/(?<!\.)\.(?!\.)|[!?\n]+/);
    let ambigua = oraciones.some(o => /\b(?:envio|caba|taller|colocacion)\b/.test(o) && (
      /\b(?:dije|dicho|dijimos|dijiste|decia|decian|habia pedido|otro pedido|me referia|antes queria|antes preferia)\b|["“”«»]/.test(o)
      || /\b(?:no estoy seguro|no estoy segura|ya no|no me decido)\b/.test(o)
      || /\bsi\s+[^,]/.test(o)));
    // Separar sólo una corrección después de una modalidad ya negada.
    // Nunca cortar entre «no» y «prefiero/elijo»: perdería el alcance de la negación.
    const segmentado = texto.replace(/\b((?:no|nunca|tampoco)\b[^,;.!?\n]{0,60}\b(?:envio|caba|taller|colocacion))\s+(?:y\s+)?(?=(?:prefiero|elijo|opto por)\b)/g, '$1, ');
    for (const fragmento of segmentado.split(/[\n,;.!]+|\bpero\b/)) {
      const f = fragmento.trim().replace(/\s+/g, ' ');
      if (!f) continue;
      const envio = /\b(?:envio|envios|envi(?:ar|en|arme)|domicilio|mandan|envian|mandamelo|mandamela|enviamelo|envienmelo|envienmela)\b/.test(f);
      const caba = /\b(?:caba|taller|colocacion)\b/.test(f);
      if (!envio && !caba) continue;
      if (/\b(?:no se|no decidi|todavia no|quizas|tal vez|depende|si es|si puedo|si pueden|si sale|si conviene)\b/.test(f) || /\bsi\b/.test(f)) { ambigua = true; continue; }
      if ((envio && caba && /\b(?:o|y)\b/.test(f)) || /\b(?:ambas|ambos|cualquiera)\b/.test(f)) { ambigua = true; continue; }
      // Preguntas, ubicación del domicilio y precios no constituyen una elección.
      if (/\b(?:por trabajo|de vacaciones|para trabajar)\b/.test(f)) continue;
      if (/[?¿]/.test(f) || /\b(?:hacen|hacias|cuanto|cuesta|tarda|donde|que costo|se puede|pueden enviar|saber)\b/.test(f)) continue;
      const niegaEnvio = envio && /\b(?:no|nunca|tampoco)\b/.test(f);
      const niegaCaba = caba && /\b(?:no|nunca|tampoco)\b/.test(f);
      if (niegaEnvio) negadas.add('envio');
      if (niegaCaba) negadas.add('caba');
      const simple = f.replace(/^(?:bueno|dale|ok|perfecto|entonces|mejor|al final)\s+/, '');
      const eleccionEnvio = /^para enviar$/.test(simple)
        || /^me (?:lo|la|los|las) (?:mandan|envian) a [a-z0-9 ]+$/.test(simple)
        || /^(?:la )?(?:opcion )?(?:de |por |con )?envio(?: a .+)?$/.test(simple)
        || /\b(?:prefiero|quiero|elijo|elegi|opto por|me quedo con|seria|necesito)\s+(?:la\s+)?(?:opcion\s+)?(?:por\s+)?envio\b/.test(f)
        || /\b(?:(?:quiero|prefiero|necesito)\s+)?que\s+me\s+(?:(?:lo|las|los)\s+)?envien\b/.test(f)
        || /\b(?:mandamelo|mandamela|envienmelo|enviamelo|envienmela)\b/.test(f)
        || /^(?:a domicilio|en mi domicilio)$/.test(simple);
      const eleccionCaba = /^(?:con )?colocacion en (?:el )?(?:taller|caba)$/.test(simple)
        || /\b(?:quiero|prefiero|necesito)\s+que\s+(?:me\s+)?(?:lo|la|los|las)\s+coloquen\s+en\s+(?:el\s+)?(?:taller|caba)\b/.test(f)
        || /^(?:(?:en|al|con)\s+)?(?:(?:el|su)\s+)?(?:caba|taller|colocacion)$/.test(simple)
        || /\b(?:prefiero|quiero|elijo|elegi|opto por|me quedo con|seria|necesito)\s+(?:la\s+)?(?:opcion\s+)?(?:en\s+)?(?:(?:el|su)\s+)?(?:caba|taller|colocacion)\b/.test(f)
        || /\b(?:voy|ire|vamos|iremos|paso|pasare|lo llevo|llevo el auto)\s+(?:a|al|por)\s+(?:el\s+)?(?:taller|caba)\b/.test(f)
